/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-ivy .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-ivy .sl-btn-primary { background-color: var(--smartlearn-primary) !important; border-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-hero-ivy .sl-btn-primary:hover { background-color: var(--smartlearn-primary-hover, var(--smartlearn-primary)) !important; filter: brightness(0.9); }
.sl-hero-ivy .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-ivy .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;0,700;1,400&display=swap');

.sl-hero-ivy {
    background-color: var(--bs-body-bg);
    position: relative;
    overflow: hidden;
    min-height: 85vh;
    display: flex;
    align-items: center;
}
.sl-hero-ivy .font-serif {
    font-family: 'Playfair Display', serif;
}
.sl-hero-ivy .tracking-wide {
    letter-spacing: 0.1em;
}
.sl-hero-ivy .bg-shape-cream {
    position: absolute;
    top: 0;
    right: 0;
    width: 45%;
    height: 100%;
    background-color: var(--bs-tertiary-bg);
    z-index: 0;
}
.sl-hero-ivy .border-body {
    border: 8px solid var(--bs-body-bg) !important;
}
.sl-hero-ivy .collage-wrapper {
    min-height: 500px;
}
.sl-hero-ivy .img-box {
    position: absolute;
    overflow: hidden;
    opacity: 0;
    transform: translateY(30px);
    animation: ivyFadeIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.sl-hero-ivy .box-1 {
    width: 65%;
    height: 60%;
    top: 0;
    left: 0;
    z-index: 2;
    animation-delay: 0.2s;
}
.sl-hero-ivy .box-2 {
    width: 55%;
    height: 50%;
    bottom: 5%;
    right: 0;
    z-index: 3;
    animation-delay: 0.4s;
}
.sl-hero-ivy .box-3 {
    width: 45%;
    height: 40%;
    bottom: -10%;
    left: 10%;
    z-index: 4;
    animation-delay: 0.6s;
}
.sl-hero-ivy .sl-ivy-text {
    opacity: 0;
    transform: translateY(20px);
    animation: ivyFadeIn 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes ivyFadeIn {
    to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 991px) {
    .sl-hero-ivy .bg-shape-cream { display: none; }
    .sl-hero-ivy .collage-wrapper { min-height: 400px; margin-top: 2rem; }
    .sl-hero-ivy .box-1 { width: 60%; height: 70%; left: 10%; top: 10%; }
    .sl-hero-ivy .box-2 { width: 50%; height: 60%; right: 10%; bottom: 0; }
    .sl-hero-ivy .box-3 { display: none; }
}

js:
(function() {
    const root = document.querySelector('.sl-hero-ivy');
    if (!root) return;
    const playBtns = root.querySelectorAll('.sl-play-btn, .sl-item-play-btn, .sl-play-overlay, [class*="play"]');
    playBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            const container = btn.closest('.position-relative') || btn.parentElement;
            const urlEl = root.querySelector('.sl-item-video-url');
            const videoUrl = urlEl ? urlEl.innerText.trim() : 'https://www.youtube.com/embed/dQw4w9WgXcQ';
            if (!container || !videoUrl) return;

            const poster = container.querySelector('img');
            if (poster) poster.style.display = 'none';
            btn.style.display = 'none';

            const iframe = document.createElement('iframe');
            iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
            iframe.style.position = 'absolute';
            iframe.style.top = '0';
            iframe.style.left = '0';
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.border = 'none';
            iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
            iframe.setAttribute('allowfullscreen', 'true');
            container.appendChild(iframe);
        });
    });
})();
